$fixture=array('synthetic_domain'=>'phase-2a2e.invalid','a'=>$targets['a']+array('a1'=>array('channel'=>'message_reference'),'a2'=>array('channel'=>'message_reference')),'b'=>$targets['b']+array('b1'=>array('channel'=>'message_reference'),'b2'=>array('channel'=>'phone')),'c1'=>$targets['c1']+array('c1'=>array('channel'=>'message_reference'),'c2'=>array('channel'=>'message_reference')),'c2'=>$targets['c2']+array('c1'=>array('channel'=>'message_reference'),'c2'=>array('channel'=>'message_reference')),'d1'=>$targets['a']+array('d1'=>array('channel'=>'message_reference'),'d2'=>array('channel'=>'message_reference')),'d2'=>$targets['b']+array('d1'=>array('channel'=>'message_reference'),'d2'=>array('channel'=>'message_reference')),'x'=>$targets['x1']+array('x1'=>$targets['x1']+array('channel'=>'message_reference'),'x2'=>$targets['x2']+array('channel'=>'phone')));update_option('dzn_phase_2a2e_concurrency_fixture',$fixture,false);update_option('dzn_phase_2a2e_concurrency_bootstrap',array('teacher'=>$teacherFixture,'run'=>$run),false);echo "Phase 2A.2-E synthetic concurrency fixture passed\n";}catch(Throwable$e){try{dzn_phase_2a0_cleanup_ready_teacher_fixture($teacherFixture);}catch(Throwable){}delete_option('dzn_phase_2a2e_concurrency_fixture');delete_option('dzn_phase_2a2e_concurrency_bootstrap');throw$e;}
